import{_ as a}from"./chunks/mixed.D5USwrGH.js";import{_ as t,o as r,c as s,a3 as i}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"À propos","description":"","frontmatter":{"title":"À propos"},"headers":[],"relativePath":"fr/projects/uix/index.md","filePath":"fr/projects/uix/index.md","lastUpdated":1794653853000}'),o={name:"fr/projects/uix/index.md"};function n(l,e,u,c,d,p){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="ui-extension-pour-home-assistant" tabindex="-1">UI eXtension pour Home Assistant <a class="header-anchor" href="#ui-extension-pour-home-assistant" aria-label="Permalink to &quot;UI eXtension pour Home Assistant&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">État vérifié le 9 novembre 2026</p><p>Les <a href="./concepts/context">contextes UIX</a> expliquent l’héritage, la priorité de la configuration directe, les règles de nom d’entité et le débogage. Les guides sur les concepts et les thèmes renvoient vers cette page. La revue couvre <strong>67</strong> pages canoniques jusqu’à <strong>9.1.0-beta.2</strong>.</p></div><blockquote><p>Cette traduction française est maintenue par UGSo Software. La documentation anglaise reste la référence. La base est la version stable <a href="https://github.com/Lint-Free-Technology/uix/releases/tag/v9.0.0" target="_blank" rel="noreferrer"><code>UIX 9.0.0</code></a> du 4 novembre 2026, révision <a href="https://github.com/Lint-Free-Technology/uix/commit/cec1191f6ee703284c75dfd3104dba9bb4419200" target="_blank" rel="noreferrer"><code>cec1191</code></a>. <strong>Home Assistant 2026.11.0 ou ultérieur est requis.</strong></p></blockquote><p><img src="'+a+'" alt="light-logo-icon"></p><h2 id="qu-est-ce-que-ui-extension" tabindex="-1">Qu&#39;est-ce que UI eXtension ? <a class="header-anchor" href="#qu-est-ce-que-ui-extension" aria-label="Permalink to &quot;Qu&#39;est-ce que UI eXtension ?&quot;">​</a></h2><p>::: note Utilisateurs de Card-mod Si vous migrez depuis Card-mod, consultez la <a href="./faq">FAQ</a>, qui répond à la plupart des questions. Pour toute autre question, utilisez les <a href="https://github.com/Lint-Free-Technology/uix/discussions" target="_blank" rel="noreferrer">discussions GitHub</a>.</p><p>::: Avec un ensemble de fonctions qui dépasse les cartes et les tableaux de bord, UI eXtension (UIX) a été créé pour étendre les possibilités du CSS personnalisé dans l&#39;interface Home Assistant. UIX s&#39;inscrit dans la continuité de <a href="https://github.com/thomasloven/lovelace-card-mod" target="_blank" rel="noreferrer">card-mod</a>, créé par <a href="https://github.com/thomasloven" target="_blank" rel="noreferrer">@thomasloven</a>.</p><p>UI eXtension comprend <a href="./using/">UIX Styling</a>, <a href="./forge/">UIX Forge</a> et <a href="./broker/">UIX Broker</a>. <a href="./using/">UIX Styling</a> permet d&#39;appliquer du CSS à presque tous les éléments de l&#39;interface Home Assistant. <a href="./forge/">UIX Forge</a> permet de créer des éléments Home Assistant (cartes, badges, lignes, etc.) avec des modèles pour toute leur configuration et des extensions avancées grâce aux <a href="./forge/sparks/">Sparks UIX Forge</a>. UIX Broker transforme les événements du navigateur, les raccourcis clavier et les événements du bus Home Assistant en interactions déclaratives. Une interaction sélectionne un élément, vérifie des règles optionnelles, puis exécute ses directives dans l&#39;ordre configuré.</p><h2 id="nouveautes-de-uix-9-0-0" tabindex="-1">Nouveautés de UIX 9.0.0 <a class="header-anchor" href="#nouveautes-de-uix-9-0-0" aria-label="Permalink to &quot;Nouveautés de UIX 9.0.0&quot;">​</a></h2><ul><li><p>Les <a href="./extras/custom-sidebar-panels">raccourcis personnalisés de barre latérale</a> ouvrent des pages Home Assistant et des sites externes. L’option d’onglet de bureau dépend de la version, de la destination et du client ; le guide détaille les restrictions actuelles et le comportement de Companion.</p></li><li><p>L’<a href="./forge/forge#visual-editor-cards-and-badges">éditeur visuel Forge</a> prend en charge les cartes et les badges. <code>element_base</code> conserve la configuration native et ses modèles.</p></li><li><p>Les <a href="./extras/uix-actions#popover">délais des popovers</a> ferment automatiquement le contenu affiché.</p></li><li><p><a href="./forge/sparks/form">Spark Formulaire</a> et <a href="./extras/uix-actions#popover">action Popover</a> pour les formulaires et les contenus superposés.</p></li><li><p><a href="./extras/style-frame-panels">Style des panneaux intégrés dans un frame</a> avec un runtime interne ; cette option expérimentale reste désactivée par défaut.</p></li><li><p><a href="./using/themes">Polices de thème avec <code>uix-fonts</code></a> et <a href="./using/images">images d&#39;entité dans les aperçus de carte</a>, avec adaptation à Home Assistant 2026.10.</p></li><li><p>Les <a href="./broker/directives#regles-de-la-directive">règles de directive Broker</a> peuvent utiliser les résultats de directives JavaScript ou template précédentes.</p></li></ul><p>L’<a href="./quick-start">installation via le Marketplace</a> ajoute automatiquement UIX comme service. La <a href="./faq">désinstallation</a> supprime aussi les Foundries, les raccourcis de barre latérale et les autres réglages du service.</p><h2 id="🚀-demarrage-rapide" tabindex="-1">🚀 Démarrage rapide <a class="header-anchor" href="#🚀-demarrage-rapide" aria-label="Permalink to &quot;🚀 Démarrage rapide&quot;">​</a></h2><p>Consultez le <a href="./quick-start">Démarrage rapide</a> pour l&#39;installation et un premier exemple de UIX Styling et UIX Forge.</p><h2 id="➡️-continuer" tabindex="-1">➡️ Continuer <a class="header-anchor" href="#➡️-continuer" aria-label="Permalink to &quot;➡️ Continuer&quot;">​</a></h2><ul><li><a href="./using/">Utiliser UIX Styling</a></li><li><a href="./forge/">Utiliser UIX Forge</a></li><li><a href="./faq">FAQ</a></li></ul>',15)])])}const h=t(o,[["render",n]]);export{g as __pageData,h as default};
